import { test, expect } from '@playwright/test';

test.describe('Login Form Validation - Empty Fields Prevention', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/login');
  });

  test('should prevent form submission when both email and password fields are empty', async ({ page }) => {
    const submitButton = page.getByRole('button', { name: /submit|login|sign in/i });

    // Verify submit button is present
    await expect(submitButton).toBeVisible();

    // Click submit without filling any fields
    await submitButton.click();

    // Verify form is still on login page (not submitted)
    await expect(page).toHaveURL(/login/);

    // Verify error message or validation feedback appears
    const emailInput = page.getByLabel(/email|username/i);
    const passwordInput = page.getByLabel(/password/i);

    // Check for HTML5 validation or custom error messages
    const emailValidation = await emailInput.evaluate((el: HTMLInputElement) => el.validationMessage);
    const passwordValidation = await passwordInput.evaluate((el: HTMLInputElement) => el.validationMessage);

    expect(emailValidation || passwordValidation).toBeTruthy();
  });

  test('should prevent form submission when only email field is filled', async ({ page }) => {
    const emailInput = page.getByLabel(/email|username/i);
    const submitButton = page.getByRole('button', { name: /submit|login|sign in/i });

    // Fill only email field
    await emailInput.fill('user@example.com');

    // Attempt to submit
    await submitButton.click();

    // Verify form is still on login page
    await expect(page).toHaveURL(/login/);

    // Verify password field has validation error
    const passwordInput = page.getByLabel(/password/i);
    const passwordValidation = await passwordInput.evaluate((el: HTMLInputElement) => el.validationMessage);

    expect(passwordValidation).toBeTruthy();
  });

  test('should prevent form submission when only password field is filled', async ({ page }) => {
    const passwordInput = page.getByLabel(/password/i);
    const submitButton = page.getByRole('button', { name: /submit|login|sign in/i });

    // Fill only password field
    await passwordInput.fill('password123');

    // Attempt to submit
    await submitButton.click();

    // Verify form is still on login page
    await expect(page).toHaveURL(/login/);

    // Verify email field has validation error
    const emailInput = page.getByLabel(/email|username/i);
    const emailValidation = await emailInput.evaluate((el: HTMLInputElement) => el.validationMessage);

    expect(emailValidation).toBeTruthy();
  });

  test('should allow form submission when both fields are properly filled', async ({ page }) => {
    const emailInput = page.getByLabel(/email|username/i);
    const passwordInput = page.getByLabel(/password/i);
    const submitButton = page.getByRole('button', { name: /submit|login|sign in/i });

    // Fill both fields
    await emailInput.fill('user@example.com');
    await passwordInput.fill('password123');

    // Submit form
    await submitButton.click();

    // Verify navigation away from login page or success message appears
    await page.waitForTimeout(1000);
    const isLoginPage = page.url().includes('login');
    const successMessage = page.getByText(/success|welcome|dashboard/i);

    const successVisible = await successMessage.isVisible().catch(() => false);
    expect(!isLoginPage || successVisible).toBeTruthy();
  });

  test('should display validation messages when attempting to submit with whitespace-only fields', async ({ page }) => {
    const emailInput = page.getByLabel(/email|username/i);
    const passwordInput = page.getByLabel(/password/i);
    const submitButton = page.getByRole('button', { name: /submit|login|sign in/i });

    // Fill fields with only whitespace
    await emailInput.fill('   ');
    await passwordInput.fill('   ');

    // Clear the fields to simulate empty state
    await emailInput.clear();
    await passwordInput.clear();

    // Attempt to submit
    await submitButton.click();

    // Verify form is still on login page
    await expect(page).toHaveURL(/login/);

    // Verify validation errors are present
    const emailValidation = await emailInput.evaluate((el: HTMLInputElement) => el.validationMessage);
    const passwordValidation = await passwordInput.evaluate((el: HTMLInputElement) => el.validationMessage);

    expect(emailValidation || passwordValidation).toBeTruthy();
  });
});
